import java.util.*;
import org.json.*;

/** Closed schema-to-CQL compiler: user strings never become executable source. */
final class SchemaCompiler {
 static final String TYPES="options timeout = 20 num_threads = 1\ntypeside Ty = literal { external_types Text -> \"java.lang.String\" Integer -> \"java.math.BigInteger\" exactReal -> \"java.math.BigDecimal\" Bool -> \"java.lang.Boolean\" external_parsers Text -> \"x => x\" Integer -> \"x => java.math.BigInteger.valueOf(0).add(new java.math.BigInteger(x))\" exactReal -> \"x => new java.math.BigDecimal(x)\" Bool -> \"x => java.lang.Boolean.valueOf(x)\" }\n";
 final JSONObject nativeSpec; final String name; final Map<String,String> symbols=new LinkedHashMap<>(); final Map<String,JSONObject> tables=new LinkedHashMap<>(); final Map<String,Map<String,String>> columns=new LinkedHashMap<>(),fks=new LinkedHashMap<>();
 SchemaCompiler(JSONObject spec,String n){nativeSpec=spec;name=n;checkKeys(spec,Set.of("tables","foreign_keys","equations"));int i=0;for(Object o:spec.getJSONArray("tables")){JSONObject t=(JSONObject)o;checkKeys(t,Set.of("id","name","columns","primaryKey","uniqueKeys"));String id=t.getString("id");if(tables.put(id,t)!=null)throw new IllegalArgumentException("Duplicate table ID "+id);symbols.put(id,n+"E"+(i++));columns.put(id,new LinkedHashMap<>());fks.put(id,new LinkedHashMap<>());int c=0;for(Object a:t.getJSONArray("columns")){JSONObject col=(JSONObject)a;checkKeys(col,Set.of("id","name","dataType","nullable","generated","storage"));String cid=col.getString("id");if(!hidden(col)&&columns.get(id).put(cid,n+"A"+i+"_"+(c++))!=null)throw new IllegalArgumentException("Duplicate column ID");type(col);}int f=0;for(Object a:foreignKeys(id)){JSONObject fk=(JSONObject)a;fks.get(id).put(fk.getString("id"),n+"F"+i+"_"+(f++));}}}
 static String type(JSONObject c){String t=switch(c.getString("dataType")){case "text"->"Text";case "integer"->"Integer";case "real"->"exactReal";case "boolean"->"Bool";default->throw new UnsupportedOperationException("Unsupported native dataType: "+c.getString("dataType"));};if(!Set.of("Text","Integer","exactReal","Bool").contains(t))throw new UnsupportedOperationException("Unsupported scalar type: "+t);return t;}
 String entity(String id){String s=symbols.get(id);if(s==null)throw new IllegalArgumentException("Unknown table ID: "+id);return s;}
 String column(String t,String id){String s=columns.get(t).get(id);if(s==null)throw new IllegalArgumentException("Unknown column ID: "+id);return s;}
 String fkTarget(JSONObject f){return f.getString("target_table");}
 String program(){validatePhysical();StringBuilder b=new StringBuilder("schema "+name+" = literal : Ty {\n entities ");for(String s:symbols.values())b.append(s).append(' ');b.append("\n foreign_keys\n");for(var e:tables.entrySet())for(Object o:foreignKeys(e.getKey())){JSONObject f=(JSONObject)o;b.append(fks.get(e.getKey()).get(f.getString("id"))).append(" : ").append(entity(e.getKey())).append(" -> ").append(entity(fkTarget(f))).append('\n');}b.append(" attributes\n");for(var e:tables.entrySet())for(Object o:e.getValue().getJSONArray("columns")){JSONObject c=(JSONObject)o;if(hidden(c))continue;b.append(column(e.getKey(),c.getString("id"))).append(" : ").append(entity(e.getKey())).append(" -> ").append(type(c)).append('\n');}JSONArray equations=new JSONArray(nativeSpec.optJSONArray("equations",new JSONArray()).toString());for(Object fo:nativeSpec.getJSONArray("foreign_keys")){JSONObject f=(JSONObject)fo;String src=f.getString("source_table"),dst=fkTarget(f);JSONArray sc=f.getJSONArray("source_columns"),tc=f.getJSONArray("target_columns");for(int j=0;j<sc.length();j++){String a=sc.getString(j),z=tc.getString(j);if(hidden(findColumn(src,a))||hidden(findColumn(dst,z)))continue;equations.put(new JSONObject().put("id","binding:"+f.getString("id")+":"+j).put("left",new JSONObject().put("source",src).put("arrows",new JSONArray().put("attribute:"+a))).put("right",new JSONObject().put("source",src).put("arrows",new JSONArray().put("reference:"+f.getString("id")).put("attribute:"+z))));}}if(equations.length()>0){b.append(" observation_equations\n");for(Object o:equations){JSONObject eq=(JSONObject)o;checkKeys(eq,Set.of("id","left","right","origin"));JSONObject l=eq.getJSONObject("left"),r=eq.getJSONObject("right");if(!l.getString("source").equals(r.getString("source")))throw new IllegalArgumentException("Equation sources differ");b.append("forall x : ").append(entity(l.getString("source"))).append(". ").append(path(l)).append(" = ").append(path(r)).append('\n');}}return b.append("}\n").toString();}
 void validatePhysical(){for(var e:tables.entrySet()){JSONObject t=e.getValue();Set<String> all=new HashSet<>();for(Object o:t.getJSONArray("columns")){JSONObject c=(JSONObject)o;c.getString("name");c.getBoolean("nullable");if(c.has("generated")&&!c.getString("generated").equals("identity"))throw new UnsupportedOperationException("Unknown generated mode");if(c.has("storage")&&!Set.of("identity","reference").contains(c.getString("storage")))throw new UnsupportedOperationException("Unknown storage mode");all.add(c.getString("id"));}for(Object k:t.getJSONArray("primaryKey"))if(!all.contains(k))throw new IllegalArgumentException("Unknown primary key column");for(Object keys:t.optJSONArray("uniqueKeys",new JSONArray()))for(Object k:(JSONArray)keys)if(!all.contains(k))throw new IllegalArgumentException("Unknown unique key column");}Set<String> seen=new HashSet<>();for(Object o:nativeSpec.getJSONArray("foreign_keys")){JSONObject f=(JSONObject)o;if(!seen.add(f.getString("id")))throw new IllegalArgumentException("Duplicate foreign key ID");String src=f.getString("source_table"),dst=fkTarget(f);entity(src);entity(dst);JSONArray sc=f.getJSONArray("source_columns"),tc=f.getJSONArray("target_columns");if(sc.isEmpty()||sc.length()!=tc.length())throw new IllegalArgumentException("Foreign key arity mismatch");for(int i=0;i<sc.length();i++){JSONObject a=findColumn(src,sc.getString(i)),b=findColumn(dst,tc.getString(i));if(!type(a).equals(type(b)))throw new IllegalArgumentException("Foreign key carrier types differ");}}}
 JSONObject findColumn(String en,String id){for(Object o:tables.get(en).getJSONArray("columns")){JSONObject c=(JSONObject)o;if(c.getString("id").equals(id))return c;}throw new IllegalArgumentException("Unknown physical column: "+id);}
 String path(JSONObject p){checkKeys(p,Set.of("source","arrows","constant"));if(p.has("constant"))throw new UnsupportedOperationException("Constant schema equations not supported yet");String en=p.getString("source"),value="x";entity(en);for(Object a:p.getJSONArray("arrows")){String arrow=(String)a;if(en==null)throw new IllegalArgumentException("Path after scalar");if(arrow.startsWith("attribute:")){value=column(en,arrow.substring(10))+"("+value+")";en=null;}else if(arrow.startsWith("reference:")){String id=arrow.substring(10),symbol=fks.get(en).get(id);if(symbol==null)throw new IllegalArgumentException("Unknown reference: "+id);value=symbol+"("+value+")";for(Object o:foreignKeys(en)){JSONObject f=(JSONObject)o;if(f.getString("id").equals(id)){en=fkTarget(f);break;}}}else throw new UnsupportedOperationException("Unknown native path arrow: "+arrow);}return value;}
 static boolean hidden(JSONObject c){return c.has("generated")||c.has("storage");}
 static void checkKeys(JSONObject x,Set<String> allowed){for(String k:x.keySet())if(!allowed.contains(k))throw new UnsupportedOperationException("Unknown native field: "+k);}
 JSONArray foreignKeys(String table){JSONArray a=new JSONArray();for(Object o:nativeSpec.getJSONArray("foreign_keys")){JSONObject f=(JSONObject)o;checkKeys(f,Set.of("id","name","source_table","source_columns","target_table","target_columns"));if(f.getString("source_table").equals(table))a.put(f);}return a;}
 JSONObject manifest(){return new JSONObject().put("schema",name).put("entities",symbols).put("attributes",columns).put("foreignKeys",fks).put("nativeSchemaSpec",nativeSpec).put("primaryKeys","preserved as metadata; no CQL uniqueness axiom inferred").put("storageAndGeneratedIdentity","preserved in nativeSchemaSpec");}
}
